import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { UserService } from 'src/app/services/emis/user.service';
import { UserSessionService } from 'src/app/services/usersession.service';

@Component({
  selector: 'app-myinspection',
  templateUrl: './myinspection.page.html',
  styleUrls: ['./myinspection.page.scss'],
})
export class MyinspectionPage implements OnInit {

  buildingDetails: any[];
  roomDetails: any[];
  CommonQuestions: any[];

  buildingActive : boolean = true;
  roomActive: boolean = false;
  sessionUserName: any;
  UdiseCode: any;
  routeData: any;
  schoolActive: boolean = false;

  constructor(private userService: UserService,
    private usersessionService: UserSessionService , private router: Router ,private route: ActivatedRoute,) { }

  ngOnInit() {

  }

  ionViewDidEnter() { 
    this.sessionUserName = this.usersessionService.emis_username();
    this.routeData = this.route.snapshot;
    this.UdiseCode = this.routeData.queryParams.Id;
    this.buildingActive = true;
    this.roomActive = false;
    this.schoolActive = false;

    this.getSchoolInfo()
  }

  getSchoolInfo() {
      this.userService.getSidsResponedData(this.sessionUserName).subscribe((res) => {
       if(res.dataStatus){
        let filter = []
          filter = res.result.filter(
           (item: any) => item.udise_code == this.UdiseCode
          );
          this.buildingDetails = filter[0].BuildingDetails;
          this.roomDetails = filter[0].RoomQuestion;
          this.CommonQuestions = filter[0].CommonQuestions;
        }else{
          this.buildingActive = false;
          this.roomActive = false;
          this.schoolActive = false;
        }
    });
  } 
  
  room() {
    this.buildingActive = false;
    this.roomActive = false;
    this.schoolActive = true
  }

  building() {
    this.buildingActive = false;
    this.roomActive = true;
    this.schoolActive = false
  }

  schoolCommon() {
    this.buildingActive = false;
    this.roomActive = true;
    this.schoolActive = false
  }

  onBack() {
    this.router.navigate(['/tabs/inspection-selection']);
    
  }
  
}
